CREATE TABLE sc_events(id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES office_users(username), business_id TEXT REFERENCES portfolio_businesses(id), title TEXT NOT NULL, person TEXT NOT NULL, location TEXT NOT NULL, start_at TEXT NOT NULL, end_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','cancelled')), revision INTEGER NOT NULL, entry_key TEXT NOT NULL, entry_digest TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(owner,entry_key));
CREATE INDEX sc_events_time ON sc_events(owner,status,start_at,end_at);
CREATE TABLE sc_settings(owner TEXT PRIMARY KEY REFERENCES office_users(username), enabled INTEGER NOT NULL DEFAULT 0, consent INTEGER NOT NULL DEFAULT 0, provider TEXT NOT NULL DEFAULT 'mock' CHECK(provider IN ('mock')), updated_at TEXT NOT NULL);
CREATE TABLE sc_notifications(id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES office_users(username), event_id TEXT REFERENCES sc_events(id), kind TEXT NOT NULL CHECK(kind IN ('daily','hour')), due_at TEXT NOT NULL, target_day TEXT, fingerprint TEXT NOT NULL, dedupe_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_at TEXT, sent_at TEXT, error_code TEXT);
CREATE TABLE sc_audit(id INTEGER PRIMARY KEY, owner TEXT NOT NULL, actor TEXT NOT NULL, ref TEXT NOT NULL, event TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE sc_ticks(id INTEGER PRIMARY KEY, executed_at TEXT NOT NULL, prepared INTEGER NOT NULL, processed INTEGER NOT NULL, error_code TEXT);
CREATE TABLE sc_work(event_id TEXT NOT NULL REFERENCES sc_events(id), revision INTEGER NOT NULL, agent TEXT NOT NULL, kind TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(event_id,revision,kind));
